87	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
88	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
89	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
90	   */
91	  priority?: boolean;
92	};
93	
94	/**
95	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
96	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
97	 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
98	 *
99	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
100	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
101	 * the slide indicator are mutually exclusive by pointer capability
102	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
103	 * exist in the DOM at all times and are gated by the recipe's own CSS media query rather than a
104	 * JS `window.matchMedia` check — matching the "keep in DOM, hide via CSS" precedent
105	 * `ZimmColourSwatchGroup` already uses for its off-page swatches — so server and client render
106	 * identically (no hydration mismatch) and neither affordance depends on `matchMedia`, which
107	 * jsdom (this component's own Vitest environment) does not implement.
108	 *
109	 * A third, always-available operability layer sits underneath both visual affordances: the
110	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
111	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
112	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
113	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
114	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
115	 */
116	export const ZimmProductCardMedia = ({
117	  primaryImage,
118	  hoverImage,
119	  images,
120	  swapOnHover,
121	  showControls,
122	  badge,
123	  onRemove,
124	  removeLabel,
125	  priority,
126	}: ZimmProductCardMediaProps) => {
127	  const intl = useIntl();
128	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
129	
130	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
131	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
132	  const gallery = images && images.length > 1 ? images : undefined;
133	  const slideImages = gallery ?? [primaryImage];
134	  const totalSlides = slideImages.length;
135	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
136	  const canPage = totalSlides > 1 && showControls;
137	  // Keyboard operability is independent of `showControls` — deliberately not folded into
138	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
139	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
140	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
141	  // so this is the only paging affordance such a user has, regardless of `showControls`.
142	  const canNavigateByKeyboard = totalSlides > 1;
143	
144	  // Single piece of state, per this codebase's extract-to-hook threshold
145	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
146	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
147	  // because this build step's file manifest is limited to this component's own 4 files; a hook
148	  // would be a 5th file outside that scope.
149	  const [currentIndex, setCurrentIndex] = useState(0);
150	  const scrollContainerRef = useRef<HTMLDivElement>(null);
151	
152	  const scrollToIndex = (index: number) => {
153	    const container = scrollContainerRef.current;
154	    if (!container || typeof container.scrollTo !== 'function') return;
155	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
156	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
157	    // browser reports a real width so the requested slide scrolls fully into view.
158	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
159	  };
160	
161	  const goToRelativeSlide = (delta: 1 | -1) => {
162	    if (totalSlides <= 1) return;
163	    const next = (currentIndex + delta + totalSlides) % totalSlides;
164	    setCurrentIndex(next);
165	    scrollToIndex(next);
166	  };
167	
168	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
169	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
170	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
171	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
172	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
173	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
174	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
175	  useEffect(() => {
176	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
177	  }, [totalSlides]);
178	
179	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
180	  // capability — additive to, and independent of, the hover-capable-only arrows and the
181	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
182	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
183	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
184	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
185	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
186	    event.preventDefault();
187	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
188	  };
189	
190	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
191	  // calls goToRelativeSlide at all. `scrollend` (Baseline 2024 — Chrome 114+, Firefox 109+,
192	  // Safari 18+) fires once the snap gesture settles. No `scroll`-event fallback for older
193	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
194	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
195	  // interaction.
196	  useEffect(() => {
197	    const container = scrollContainerRef.current;
198	    if (!container || totalSlides <= 1) return undefined;
199	
200	    const handleScrollEnd = () => {
201	      const slideWidth = container.clientWidth || 1;
202	      const nearest = Math.round(container.scrollLeft / slideWidth);
203	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
204	    };
205	
206	    container.addEventListener('scrollend', handleScrollEnd);
207	    return () => container.removeEventListener('scrollend', handleScrollEnd);
208	  }, [totalSlides]);
209	
210	  // Non-primary images are always lazy; only the first slide's own base image can opt into
211	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
212	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
213	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
214	
215	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
216	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
217	  const hasBadge = typeof badge === 'string' && badge.trim().length > 0;
218	
219	  return (
220	    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.media}>
221	      <chakra.div
222	        ref={scrollContainerRef}
223	        __css={styles.scrollContainer}
224	        data-testid="card-media-scroll"
225	        role={canNavigateByKeyboard ? 'group' : undefined}
226	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
227	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
228	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
229	      >
230	        {slideImages.map((image, index) => {
231	          const isPrimaryPosition = index === 0;
232	
233	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
234	            return (
235	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
236	                <chakra.img
237	                  src={image.src}
238	                  alt={image.alt}
239	                  data-role="hover-base"
240	                  __css={styles.hoverSwapBase}
241	                  {...imageLoadingProps(true)}
242	                />
243	                <chakra.img
244	                  src={hoverImage.src}
245	                  alt={hoverImage.alt}
246	                  data-role="hover-overlay"
247	                  __css={styles.hoverSwapOverlay}
248	                  {...imageLoadingProps(false)}
249	                />
250	              </chakra.div>
251	            );
252	          }
253	
254	          return (
255	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
256	              <chakra.img
257	                src={image.src}
258	                alt={image.alt}
259	                __css={styles.image}
260	                {...imageLoadingProps(isPrimaryPosition)}
261	              />
262	            </chakra.div>
263	          );
264	        })}
265	      </chakra.div>
266	
267	      {hasBadge && (
268	        <chakra.div __css={styles.badge} data-card-slot={CARD_SLOT.badge}>
269	          <chakra.span __css={styles.badgeLabel}>{badge}</chakra.span>
270	        </chakra.div>
271	      )}
272	
273	      {showRemove && (
274	        <chakra.button
275	          type="button"
276	          __css={styles.close}
277	          data-card-slot={CARD_SLOT.close}
278	          aria-label={removeLabel}
279	          onClick={onRemove}
280	        >
281	          <CloseIcon aria-hidden boxSize="var(--zimm-icon-size-md)" />
282	        </chakra.button>
283	      )}
284	
285	      {canPage && (
286	        <chakra.div __css={styles.carousel} data-card-slot={CARD_SLOT.carousel}>
287	          <chakra.button
288	            type="button"
289	            __css={styles.arrowButton}
290	            aria-label={intl.formatMessage(messages.previousImage)}
291	            onClick={() => goToRelativeSlide(-1)}
292	          >
293	            <ChevronLeftIcon aria-hidden />
294	          </chakra.button>
295	          <chakra.button
296	            type="button"
297	            __css={styles.arrowButton}
298	            aria-label={intl.formatMessage(messages.nextImage)}
299	            onClick={() => goToRelativeSlide(1)}
300	          >
301	            <ChevronRightIcon aria-hidden />
302	          </chakra.button>
303	        </chakra.div>
304	      )}
305	
306	      {totalSlides > 1 && (
307	        <chakra.div __css={styles.indicatorWrapper} data-card-slot={CARD_SLOT.indicator}>
308	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
309	        </chakra.div>
310	      )}
311	    </chakra.div>
312	  );
313	};
314	
315	export default ZimmProductCardMedia;
