import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';

const ZIMM_PRODUCT_NAME_RECIPE = 'ZimmProductName';

type ZimmProductNameProps = {
  /**
   * The product's display name, already resolved by the caller.
   *
   * Stays required rather than becoming `name?: string` like the sibling atoms' optional props.
   * Those are optional because their own page mapper genuinely produces an absent value —
   * `selectPdpProductInfo` resolves a missing price to `''`. The name is the opposite case: that
   * mapper returns `null` for the whole object when the name is absent, so no PDP render ever
   * reaches this atom without one. Widening the type would give up a compile-time guarantee to
   * describe a state the page cannot produce. The guard below covers the empty string, which is
   * the one absent-ish value `string` still admits.
   */
  name: string;
  /**
   * Heading level. Required rather than defaulted: the correct level depends on what else the
   * page has already emitted, and a silent `h1` default duplicates the base PDP's own
   * screen-reader-only `<h1>Product Details</h1>`.
   */
  as: 'h1' | 'h2' | 'h3';
};

/**
 * Atom — the product name. All styling, type included, lives in `zimmProductName.css.ts` and is
 * consumed through the theme, per the one-canonical-styling-surface rule — the element carries no
 * style prop of its own, so the recipe cannot be out-ranked by one.
 *
 * Renders nothing when the name is empty, so a caller can place it unconditionally — the same
 * contract as `ZimmProductPrice` and `ZimmProductDescription`. The guard lives here and not only
 * at the call site: `selectPdpProductInfo` already returns `null` without a name, but that covers
 * one caller. An empty `heading3` node still occupies a row in `ZimmProductContent`'s flex column
 * and still takes the column's 20px `gap`, so any other caller passing `''` would get a hole
 * where the name should be. Fixed at the atom, not at each call site.
 *
 * The element is written as `chakra.p` with an `as` override rather than a fixed heading tag,
 * which is what Chakra's own `Text` did before the recipe landed: the tag is a caller decision
 * and `as` is the only prop that can carry it. `index.stories.tsx` asserts the heading role and
 * level for all three values so this cannot silently degrade to a `<p>`.
 */
export const ZimmProductName = ({ name, as }: ZimmProductNameProps) => {
  // Guard below the hook, never above it: an early return before `useStyleConfig` makes the hook
  // call conditional, which `react-hooks/rules-of-hooks` reports as an error rather than a
  // warning. Same ordering as `ZimmProductPrice` and `ZimmProductModelInfo`.
  const styles = useStyleConfig(ZIMM_PRODUCT_NAME_RECIPE, {});
  if (!name) return null;

  return (
    <chakra.p as={as} __css={styles} data-testid="product-name">
      {name}
    </chakra.p>
  );
};

