/**
 * Keyboard navigation — ArrowRight/Left move colour selection without mouse.
 *
 * Swatches have no `href` so ArrowKey presses call `onSelect` (linkless path) rather than
 * `history.push` — this lets the `play` assert on the emitted value without depending on
 * router state that the story does not control.
 */
export const KeyboardNavigation: Story = {
  args: {
    label: 'Colour',
    values: [
      v('raspberry', 'Raspberry', { href: undefined }),
      v('ivory', 'Ivory', { href: undefined }),
      v('navy', 'Navy', { href: undefined }),
    ],
    selectedValue: 'raspberry',
    onSelect: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const swatches = canvas.getAllByRole('radio');

    // Start focused on Raspberry (index 0) and navigate right → Ivory (index 1).
    swatches[0].focus();
    await userEvent.keyboard('{ArrowRight}');
    await expect(args.onSelect).toHaveBeenCalledWith('ivory');

    // ArrowLeft from Raspberry wraps to the last swatch (Navy, index 2).
    await userEvent.keyboard('{ArrowLeft}');
    await expect(args.onSelect).toHaveBeenCalledWith('navy');
  },
};

